def current_workspace(request):
    if not request.user.is_authenticated:
        return None
    return (
        Workspace.objects.filter(members__user=request.user)
        .select_related("plan", "subscription")
        .order_by("id")
        .first()
    )

def require_role(*roles):
    def decorator(view):
        @wraps(view)
        def wrapped(request, *args, **kwargs):
            membership = request.workspace.members.get(user=request.user)
            if membership.role not in roles:
                raise PermissionDenied
            return view(request, *args, **kwargs)
        return wrapped
    return decorator

@require_role("owner", "admin")
def invite_member(request):
    form = InviteForm(request.POST or None)
    if request.method == "POST" and form.is_valid():
        invitation = form.save(commit=False)
        invitation.workspace = request.workspace
        invitation.invited_by = request.user
        invitation.save()
        transaction.on_commit(
            lambda: send_invitation.enqueue(invitation.pk)
        )
        return redirect("members")
    return render(request, "workspace/invite.html", {"form": form})

def public_article(request, slug):
    article = get_object_or_404(
        Article.objects.filter(
            status=Article.Status.PUBLISHED,
            published_at__lte=timezone.now(),
        ).prefetch_related("revisions"),
        slug=slug,
    )
    return render(request, "public/article.html", {"article": article})

@require_POST
def publish_article(request, pk):
    article = get_object_or_404(Article, pk=pk)
    if not request.user.has_perm("content.publish_article", article):
        raise PermissionDenied

    with transaction.atomic():
        article.status = Article.Status.PUBLISHED
        article.published_at = timezone.now()
        article.save(update_fields=["status", "published_at", "updated_at"])
        ArticleRevision.objects.create(...)
        transaction.on_commit(lambda: invalidate_article_cache.delay(article.pk))
    return redirect("editorial:article", pk=article.pk)

def inbound_email(request):
    payload = json.loads(request.body)
    event_id = payload["event_id"]

    with transaction.atomic():
        event, created = InboundEvent.objects.get_or_create(
            provider="email", event_id=event_id
        )
        if not created:
            return HttpResponse(status=200)

        ticket = match_or_create_ticket(payload)
        message = Message.objects.create(
            ticket=ticket,
            author=get_or_create_contact(payload["from"]),
            body=clean_inbound_body(payload["text"]),
            is_internal=False,
        )
        if payload.get("attachments"):
            enqueue_attachment_processing(message.pk, payload["attachments"])

    return HttpResponse(status=200)

class PostViewSet(viewsets.ModelViewSet):
    serializer_class = PostSerializer
    permission_classes = [IsAuthenticated]
    pagination_class = CursorPagination

    def get_queryset(self):
        return (
            Post.objects.filter(author__in=self.request.user.following_ids())
            .select_related("author")
            .order_by("-created_at", "-id")
        )

    def perform_create(self, serializer):
        serializer.save(author=self.request.user)

